package com.ekzellence.watch;
import android.content.*;
import android.database.*;
import android.database.sqlite.*;
import android.net.Uri;
import android.os.*;
import android.provider.DocumentsContract;
import androidx.documentfile.provider.DocumentFile;
import java.io.*;
import org.json.*;

public class Store extends SQLiteOpenHelper {
 final Context context;
 final android.content.SharedPreferences prefs;
 final Security security;
 public Store(Context c,Security sec){super(c,"watch.db",null,2);context=c;prefs=c.getSharedPreferences("watch",0);security=sec;getWritableDatabase();}
 public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE cameras(id TEXT PRIMARY KEY,name TEXT NOT NULL,type TEXT NOT NULL,source TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 0)");d.execSQL("CREATE TABLE recordings(id INTEGER PRIMARY KEY AUTOINCREMENT,camera TEXT NOT NULL,uri TEXT NOT NULL,start INTEGER NOT NULL,end INTEGER NOT NULL,size INTEGER NOT NULL,cloud INTEGER NOT NULL DEFAULT 0,attempts INTEGER NOT NULL DEFAULT 0,retryAfter INTEGER NOT NULL DEFAULT 0,lastError TEXT NOT NULL DEFAULT '')");d.execSQL("CREATE INDEX time_camera ON recordings(camera,start)");ContentValues v=new ContentValues();v.put("id","usb");v.put("name","Main camera");v.put("type","usb");v.put("source","");d.insert("cameras",null,v);}
 public void onUpgrade(SQLiteDatabase d,int a,int b){if(a<2){d.execSQL("ALTER TABLE recordings ADD COLUMN attempts INTEGER NOT NULL DEFAULT 0");d.execSQL("ALTER TABLE recordings ADD COLUMN retryAfter INTEGER NOT NULL DEFAULT 0");d.execSQL("ALTER TABLE recordings ADD COLUMN lastError TEXT NOT NULL DEFAULT ''");}}
 String cameraName(String id){try(Cursor c=getReadableDatabase().rawQuery("SELECT name FROM cameras WHERE id=?",new String[]{id})){return c.moveToFirst()?c.getString(0):id;}}
 void removeVerifiedLocal(long id,Uri uri){try(Cursor c=getReadableDatabase().rawQuery("SELECT cloud FROM recordings WHERE id=?",new String[]{""+id})){if(!c.moveToFirst()||c.getInt(0)!=1)return;try{if(uri.getScheme().equals("file"))new File(uri.getPath()).delete();else DocumentsContract.deleteDocument(context.getContentResolver(),uri);}catch(Exception ignored){}}}
 JSONObject queueStatus()throws Exception{try(Cursor c=getReadableDatabase().rawQuery("SELECT COUNT(*),COALESCE(SUM(size),0),COALESCE(MIN(start),0) FROM recordings WHERE cloud=0",null)){c.moveToFirst();return new JSONObject().put("pending",c.getLong(0)).put("bytes",c.getLong(1)).put("oldest",c.getLong(2));}}
 synchronized JSONArray cameras(boolean secrets)throws Exception{JSONArray a=new JSONArray();try(Cursor c=getReadableDatabase().rawQuery("SELECT * FROM cameras ORDER BY type DESC,name",null)){while(c.moveToNext()){JSONObject j=new JSONObject();j.put("id",c.getString(0));j.put("name",c.getString(1));j.put("type",c.getString(2));j.put("enabled",c.getInt(4)==1);if(secrets)j.put("source",c.getString(3).isEmpty()?"":security.decrypt(c.getString(3)));a.put(j);}}return a;}
 synchronized String saveCamera(JSONObject j)throws Exception{String name=j.optString("name").trim();if(name.isEmpty()||name.length()>60)throw new Exception("Camera name must be 1–60 characters");String id=j.optString("id","");String type=j.optString("type","rtsp");if(id.isEmpty()){if(cameras(false).length()>=4)throw new Exception("Beta supports up to 4 cameras; tablet capacity requires testing");id=java.util.UUID.randomUUID().toString();}else{boolean found=false;JSONArray a=cameras(false);for(int i=0;i<a.length();i++)if(a.getJSONObject(i).getString("id").equals(id)){type=a.getJSONObject(i).getString("type");found=true;}if(!found)throw new Exception("Unknown camera");}ContentValues v=new ContentValues();v.put("id",id);v.put("name",name);v.put("type",type);if(!type.equals("usb")){String src=j.optString("source");if(!src.startsWith("rtsp://"))throw new Exception("Use an RTSP URL with an H.264 stream");v.put("source",security.encrypt(src));}else v.put("source","");v.put("enabled",0);getWritableDatabase().insertWithOnConflict("cameras",null,v,SQLiteDatabase.CONFLICT_REPLACE);return id;}
 void enabled(String id,boolean b){ContentValues v=new ContentValues();v.put("enabled",b?1:0);getWritableDatabase().update("cameras",v,"id=?",new String[]{id});}
 File temp(String camera){File f=new File(context.getFilesDir(),"pending/"+camera);f.mkdirs();return new File(f,System.currentTimeMillis()+".mp4");}
 synchronized void finish(String camera,File f,long start,long end)throws Exception{if(!f.exists()||f.length()<1000){f.delete();return;}String tree=prefs.getString("tree","");Uri uri;
 if(tree.isEmpty()){File dir=new File(context.getFilesDir(),"recordings/"+camera);dir.mkdirs();File target=new File(dir,f.getName());if(!f.renameTo(target))throw new IOException("Could not finalize recording");uri=Uri.fromFile(target);}else{DocumentFile root=DocumentFile.fromTreeUri(context,Uri.parse(tree));if(root==null||!root.canWrite())throw new IOException("SD folder permission lost; recording kept in pending");DocumentFile dir=root.findFile(camera);if(dir==null)dir=root.createDirectory(camera);if(dir==null)throw new IOException("Cannot create camera folder");DocumentFile target=dir.createFile("video/mp4",f.getName());if(target==null)throw new IOException("Cannot create recording");uri=target.getUri();try(InputStream in=new FileInputStream(f);OutputStream out=context.getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException("SD card unavailable");NativeDownload.copy(in,out);}catch(Exception e){target.delete();throw e;}f.delete();}
 ContentValues v=new ContentValues();v.put("camera",camera);v.put("uri",uri.toString());v.put("start",start);v.put("end",end);v.put("size",size(uri));getWritableDatabase().insertOrThrow("recordings",null,v);WatchService service=WatchService.instance;if(service!=null)service.requestUpload();}
 long size(Uri u){try{if(u.getScheme().equals("file"))return new File(u.getPath()).length();try(android.os.ParcelFileDescriptor p=context.getContentResolver().openFileDescriptor(u,"r")){return p.getStatSize();}}catch(Exception e){return 0;}}
 JSONArray recordings(String camera,long since,long until)throws Exception{JSONArray a=new JSONArray();try(Cursor c=getReadableDatabase().rawQuery("SELECT id,camera,start,end,size,cloud FROM recordings WHERE (?='' OR camera=?) AND end>=? AND start<=? ORDER BY start DESC LIMIT 500",new String[]{camera,camera,""+since,""+until})){while(c.moveToNext()){JSONObject j=new JSONObject();j.put("id",c.getLong(0));j.put("camera",c.getString(1));j.put("start",c.getLong(2));j.put("end",c.getLong(3));j.put("size",c.getLong(4));j.put("cloud",c.getInt(5)==1);j.put("cloudOnly",c.getInt(5)==1&&prefs.getBoolean("cloudPrimary",false));a.put(j);}}return a;}
 Uri recording(long id)throws Exception{try(Cursor c=getReadableDatabase().rawQuery("SELECT uri FROM recordings WHERE id=?",new String[]{""+id})){if(!c.moveToFirst())throw new FileNotFoundException("Recording not found");return Uri.parse(c.getString(0));}}
 long free(){String tree=prefs.getString("tree","");try{if(!tree.isEmpty()){android.os.storage.StorageManager sm=context.getSystemService(android.os.storage.StorageManager.class);String doc=DocumentsContract.getTreeDocumentId(Uri.parse(tree));String vol=doc.split(":")[0];for(android.os.storage.StorageVolume v:sm.getStorageVolumes()){if(v.getUuid()!=null&&v.getUuid().equalsIgnoreCase(vol)&&Build.VERSION.SDK_INT>=30&&v.getDirectory()!=null)return v.getDirectory().getUsableSpace();}return -1;}}catch(Exception ignored){return -1;}return context.getFilesDir().getUsableSpace();}
 boolean hasRoom(){long f=free();return context.getFilesDir().getUsableSpace()>512L*1024*1024&&(f<0||f>512L*1024*1024);}
 synchronized int cleanup(long now){int count=0;long cutoff=Retention.cutoff(now);try(Cursor c=getReadableDatabase().rawQuery("SELECT id,uri FROM recordings WHERE end<? AND (?=0 OR cloud=1)",new String[]{""+cutoff,prefs.getBoolean("cloudEnabled",false)?"1":"0"})){while(c.moveToNext()){Uri u=Uri.parse(c.getString(1));try{boolean gone=u.getScheme().equals("file")?(!new File(u.getPath()).exists()||new File(u.getPath()).delete()):DocumentsContract.deleteDocument(context.getContentResolver(),u);if(gone){getWritableDatabase().delete("recordings","id=?",new String[]{c.getString(0)});count++;}}catch(Exception ignored){}}}return count;}
}
